CREATE TABLE IF NOT EXISTS "vehicles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle identification number. The only identifier that survives a re-registration, so it is the natural key.
	"vin" VARCHAR(17) NOT NULL UNIQUE,
	-- Current plate. Not unique over time — plates get reassigned between vehicles and countries, which is why the VIN carries the uniqueness.
	"registration_plate" VARCHAR(16) NOT NULL,
	-- Manufacturer, e.g. Ford.
	"make" VARCHAR(60) NOT NULL,
	-- Model name, used to match service intervals and parts.
	"model" VARCHAR(60) NOT NULL,
	-- Model year, which is not always the year of purchase.
	"model_year" SMALLINT,
	-- car | van | truck | tractor | trailer | forklift. Drives which licence class a driver needs.
	"vehicle_type" VARCHAR(24) NOT NULL DEFAULT 'van',
	-- diesel | petrol | lpg | electric | hybrid. Electric vehicles report state of charge where the rest report a fuel level, and cost per kilometre is computed differently.
	"fuel_type" VARCHAR(16) NOT NULL DEFAULT 'diesel',
	-- owned | leased | rented. Leased vehicles have a return condition and a mileage cap, which changes how hard you chase damage.
	"ownership" VARCHAR(16) NOT NULL DEFAULT 'owned',
	-- Lease end date. Null when owned. Drives the end-of-term inspection reminder.
	"lease_ends_on" DATE,
	-- Date the vehicle entered the fleet. Cost per kilometre is meaningless without it.
	"acquired_on" DATE,
	-- Date it left the fleet. Set rather than deleting the row, because work orders and incidents must still resolve.
	"disposed_on" DATE,
	-- Last known odometer in kilometres, maintained from the newest telematics sample. A cached value: maintenance due checks read it thousands of times a day and must not scan the sample table.
	"odometer_km" INTEGER NOT NULL DEFAULT 0,
	-- Site the vehicle is normally kept at, used for scheduling workshop slots.
	"home_base" VARCHAR(120),
	-- active | in_shop | reserve | sold. in_shop is what makes a vehicle invisible to dispatch without deleting its assignment.
	"status" VARCHAR(24) NOT NULL DEFAULT 'active',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "vehicles" IS 'One row per physical vehicle for its whole life in the fleet. The odometer is denormalised here on purpose; everything else about its condition is derived from the tables below.';
COMMENT ON COLUMN "vehicles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "vehicles"."vin" IS 'Vehicle identification number. The only identifier that survives a re-registration, so it is the natural key.';
COMMENT ON COLUMN "vehicles"."registration_plate" IS 'Current plate. Not unique over time — plates get reassigned between vehicles and countries, which is why the VIN carries the uniqueness.';
COMMENT ON COLUMN "vehicles"."make" IS 'Manufacturer, e.g. Ford.';
COMMENT ON COLUMN "vehicles"."model" IS 'Model name, used to match service intervals and parts.';
COMMENT ON COLUMN "vehicles"."model_year" IS 'Model year, which is not always the year of purchase.';
COMMENT ON COLUMN "vehicles"."vehicle_type" IS 'car | van | truck | tractor | trailer | forklift. Drives which licence class a driver needs.';
COMMENT ON COLUMN "vehicles"."fuel_type" IS 'diesel | petrol | lpg | electric | hybrid. Electric vehicles report state of charge where the rest report a fuel level, and cost per kilometre is computed differently.';
COMMENT ON COLUMN "vehicles"."ownership" IS 'owned | leased | rented. Leased vehicles have a return condition and a mileage cap, which changes how hard you chase damage.';
COMMENT ON COLUMN "vehicles"."lease_ends_on" IS 'Lease end date. Null when owned. Drives the end-of-term inspection reminder.';
COMMENT ON COLUMN "vehicles"."acquired_on" IS 'Date the vehicle entered the fleet. Cost per kilometre is meaningless without it.';
COMMENT ON COLUMN "vehicles"."disposed_on" IS 'Date it left the fleet. Set rather than deleting the row, because work orders and incidents must still resolve.';
COMMENT ON COLUMN "vehicles"."odometer_km" IS 'Last known odometer in kilometres, maintained from the newest telematics sample. A cached value: maintenance due checks read it thousands of times a day and must not scan the sample table.';
COMMENT ON COLUMN "vehicles"."home_base" IS 'Site the vehicle is normally kept at, used for scheduling workshop slots.';
COMMENT ON COLUMN "vehicles"."status" IS 'active | in_shop | reserve | sold. in_shop is what makes a vehicle invisible to dispatch without deleting its assignment.';

CREATE INDEX "idx_vehicles_status_type"
ON "vehicles" ("status", "vehicle_type");

CREATE TABLE IF NOT EXISTS "drivers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Payroll or staff identifier, the join key to the HR system.
	"employee_code" VARCHAR(32) NOT NULL UNIQUE,
	-- Name as it appears on the licence, which is what an inspector checks against.
	"full_name" VARCHAR(160) NOT NULL,
	-- Contact address for licence expiry reminders.
	"email" VARCHAR(320),
	-- Mobile number, used by dispatch and by roadside assistance.
	"phone" VARCHAR(32),
	-- Start date, used for tenure-based insurance rating.
	"hired_on" DATE,
	-- Leaving date. Null while employed. Kept so historical assignments and incidents still resolve.
	"terminated_on" DATE,
	-- active | suspended | on_leave | terminated. Suspended is separate from terminated because a suspended driver still holds equipment.
	"status" VARCHAR(24) NOT NULL DEFAULT 'active',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "drivers" IS 'A person who may be assigned a vehicle. Deliberately thin: the safety and compliance picture is assembled from licences, inspections and incidents rather than stored as scores here.';
COMMENT ON COLUMN "drivers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "drivers"."employee_code" IS 'Payroll or staff identifier, the join key to the HR system.';
COMMENT ON COLUMN "drivers"."full_name" IS 'Name as it appears on the licence, which is what an inspector checks against.';
COMMENT ON COLUMN "drivers"."email" IS 'Contact address for licence expiry reminders.';
COMMENT ON COLUMN "drivers"."phone" IS 'Mobile number, used by dispatch and by roadside assistance.';
COMMENT ON COLUMN "drivers"."hired_on" IS 'Start date, used for tenure-based insurance rating.';
COMMENT ON COLUMN "drivers"."terminated_on" IS 'Leaving date. Null while employed. Kept so historical assignments and incidents still resolve.';
COMMENT ON COLUMN "drivers"."status" IS 'active | suspended | on_leave | terminated. Suspended is separate from terminated because a suspended driver still holds equipment.';

CREATE INDEX "idx_drivers_status"
ON "drivers" ("status");

CREATE TABLE IF NOT EXISTS "driver_licences" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Holder of the licence.
	"driver_id" BIGINT NOT NULL,
	-- Number as printed. Not globally unique because two countries can issue the same string.
	"licence_number" VARCHAR(64) NOT NULL,
	-- ISO 3166-1 alpha-2 code of the issuing authority, which is half of what makes the number unique.
	"issuing_country" CHAR(2) NOT NULL,
	-- State or province, needed where licensing is not national.
	"issuing_region" VARCHAR(80),
	-- Category the holder may drive, e.g. B, C, CE, D. Matched against vehicles.vehicle_type before an assignment is allowed.
	"licence_class" VARCHAR(16) NOT NULL,
	-- Additional entitlement such as hazmat, tanker or passenger. Expires on its own schedule, which is why one driver has several rows.
	"endorsement" VARCHAR(40),
	-- Issue date, occasionally required on insurance declarations.
	"issued_on" DATE NOT NULL,
	-- Expiry date. The single most important column here: a driver who drives on an expired entitlement voids the insurance on the load.
	"expires_on" DATE NOT NULL,
	-- When someone last checked the physical document or the licensing authority API. An unverified licence is not the same as a valid one.
	"verified_at" TIMESTAMPTZ,
	-- valid | expiring | expired | suspended | revoked. Suspensions arrive from the authority between expiry dates, so status is not derivable from expires_on alone.
	"status" VARCHAR(24) NOT NULL DEFAULT 'valid',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "driver_licences" IS 'One row per entitlement, not per driver. A licence is a set of classes and endorsements with independent expiry dates, and flattening them into columns on drivers is what makes the expiry report impossible to write.';
COMMENT ON COLUMN "driver_licences"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "driver_licences"."driver_id" IS 'Holder of the licence.';
COMMENT ON COLUMN "driver_licences"."licence_number" IS 'Number as printed. Not globally unique because two countries can issue the same string.';
COMMENT ON COLUMN "driver_licences"."issuing_country" IS 'ISO 3166-1 alpha-2 code of the issuing authority, which is half of what makes the number unique.';
COMMENT ON COLUMN "driver_licences"."issuing_region" IS 'State or province, needed where licensing is not national.';
COMMENT ON COLUMN "driver_licences"."licence_class" IS 'Category the holder may drive, e.g. B, C, CE, D. Matched against vehicles.vehicle_type before an assignment is allowed.';
COMMENT ON COLUMN "driver_licences"."endorsement" IS 'Additional entitlement such as hazmat, tanker or passenger. Expires on its own schedule, which is why one driver has several rows.';
COMMENT ON COLUMN "driver_licences"."issued_on" IS 'Issue date, occasionally required on insurance declarations.';
COMMENT ON COLUMN "driver_licences"."expires_on" IS 'Expiry date. The single most important column here: a driver who drives on an expired entitlement voids the insurance on the load.';
COMMENT ON COLUMN "driver_licences"."verified_at" IS 'When someone last checked the physical document or the licensing authority API. An unverified licence is not the same as a valid one.';
COMMENT ON COLUMN "driver_licences"."status" IS 'valid | expiring | expired | suspended | revoked. Suspensions arrive from the authority between expiry dates, so status is not derivable from expires_on alone.';

CREATE UNIQUE INDEX "uq_licences_driver_class_endorsement"
ON "driver_licences" ("driver_id", "licence_class", "endorsement");
CREATE INDEX "idx_licences_expiry"
ON "driver_licences" ("expires_on");

CREATE TABLE IF NOT EXISTS "vehicle_assignments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle handed over.
	"vehicle_id" BIGINT NOT NULL,
	-- Driver responsible for it.
	"driver_id" BIGINT NOT NULL,
	-- primary | temporary | pool. A pool assignment is per shift; a primary one can run for years.
	"assignment_type" VARCHAR(24) NOT NULL DEFAULT 'primary',
	-- Handover time. The lower bound of the interval this driver is accountable for.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- Return time. Null means the assignment is current, which is what makes "who has this van right now" a single indexed lookup.
	"ended_at" TIMESTAMPTZ,
	-- Odometer at handover, so fuel efficiency and damage can be attributed to the right driver.
	"start_odometer_km" INTEGER,
	-- Odometer at return. The difference is the distance this driver is answerable for.
	"end_odometer_km" INTEGER,
	-- Free text recorded at handover, typically pre-existing damage nobody wants to argue about later.
	"handover_notes" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "vehicle_assignments" IS 'Custody over time, modelled as a half-open interval. Everything that costs money — fuel, damage, a speeding ticket — is attributed by finding the assignment covering the event timestamp, so overlapping rows for one vehicle must be excluded by constraint, not by convention.';
COMMENT ON COLUMN "vehicle_assignments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "vehicle_assignments"."vehicle_id" IS 'Vehicle handed over.';
COMMENT ON COLUMN "vehicle_assignments"."driver_id" IS 'Driver responsible for it.';
COMMENT ON COLUMN "vehicle_assignments"."assignment_type" IS 'primary | temporary | pool. A pool assignment is per shift; a primary one can run for years.';
COMMENT ON COLUMN "vehicle_assignments"."started_at" IS 'Handover time. The lower bound of the interval this driver is accountable for.';
COMMENT ON COLUMN "vehicle_assignments"."ended_at" IS 'Return time. Null means the assignment is current, which is what makes "who has this van right now" a single indexed lookup.';
COMMENT ON COLUMN "vehicle_assignments"."start_odometer_km" IS 'Odometer at handover, so fuel efficiency and damage can be attributed to the right driver.';
COMMENT ON COLUMN "vehicle_assignments"."end_odometer_km" IS 'Odometer at return. The difference is the distance this driver is answerable for.';
COMMENT ON COLUMN "vehicle_assignments"."handover_notes" IS 'Free text recorded at handover, typically pre-existing damage nobody wants to argue about later.';

CREATE INDEX "idx_assignments_vehicle_start"
ON "vehicle_assignments" ("vehicle_id", "started_at");
CREATE INDEX "idx_assignments_driver_start"
ON "vehicle_assignments" ("driver_id", "started_at");

CREATE TABLE IF NOT EXISTS "telematics_samples" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle the sample came from.
	"vehicle_id" BIGINT NOT NULL,
	-- Device clock time of the sample, not ingest time. Devices buffer while out of coverage and replay later, so rows arrive out of order.
	"recorded_at" TIMESTAMPTZ NOT NULL,
	-- interval | ignition_on | ignition_off | harsh_event | geofence | fault. Why this ping was kept when its neighbours were dropped.
	"sample_reason" VARCHAR(24) NOT NULL DEFAULT 'interval',
	-- Odometer reading. Null when the device cannot read the bus and only has GPS distance.
	"odometer_km" INTEGER,
	-- Cumulative engine hours. For plant and refrigerated units this, not distance, is what drives the service interval.
	"engine_hours" NUMERIC(10,1),
	-- Tank level or state of charge as a percentage. A fall with the ignition off is the classic fuel theft signal.
	"fuel_level_pct" SMALLINT,
	-- Speed at the sample instant, kept for harsh-event context rather than for continuous speed reporting.
	"speed_kph" SMALLINT,
	-- WGS84 latitude. Six decimal places is roughly ten centimetres, which is far beyond what the GPS fix justifies but keeps rounding out of route replays.
	"latitude" NUMERIC(9,6),
	-- WGS84 longitude.
	"longitude" NUMERIC(9,6),
	-- Ignition state, which separates driving time from idling and from a parked vehicle reporting on a keepalive.
	"ignition_on" BOOLEAN,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "telematics_samples" IS 'Downsampled telematics, not the raw feed. A tracker emits a position every few seconds; at fleet scale that is billions of rows a year that nobody queries. What is kept is a fixed-interval sample plus every state change that carries meaning, which answers every question the fleet actually asks at a fraction of the volume.';
COMMENT ON COLUMN "telematics_samples"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "telematics_samples"."vehicle_id" IS 'Vehicle the sample came from.';
COMMENT ON COLUMN "telematics_samples"."recorded_at" IS 'Device clock time of the sample, not ingest time. Devices buffer while out of coverage and replay later, so rows arrive out of order.';
COMMENT ON COLUMN "telematics_samples"."sample_reason" IS 'interval | ignition_on | ignition_off | harsh_event | geofence | fault. Why this ping was kept when its neighbours were dropped.';
COMMENT ON COLUMN "telematics_samples"."odometer_km" IS 'Odometer reading. Null when the device cannot read the bus and only has GPS distance.';
COMMENT ON COLUMN "telematics_samples"."engine_hours" IS 'Cumulative engine hours. For plant and refrigerated units this, not distance, is what drives the service interval.';
COMMENT ON COLUMN "telematics_samples"."fuel_level_pct" IS 'Tank level or state of charge as a percentage. A fall with the ignition off is the classic fuel theft signal.';
COMMENT ON COLUMN "telematics_samples"."speed_kph" IS 'Speed at the sample instant, kept for harsh-event context rather than for continuous speed reporting.';
COMMENT ON COLUMN "telematics_samples"."latitude" IS 'WGS84 latitude. Six decimal places is roughly ten centimetres, which is far beyond what the GPS fix justifies but keeps rounding out of route replays.';
COMMENT ON COLUMN "telematics_samples"."longitude" IS 'WGS84 longitude.';
COMMENT ON COLUMN "telematics_samples"."ignition_on" IS 'Ignition state, which separates driving time from idling and from a parked vehicle reporting on a keepalive.';

CREATE INDEX "idx_telematics_vehicle_time"
ON "telematics_samples" ("vehicle_id", "recorded_at");
CREATE INDEX "idx_telematics_vehicle_reason_time"
ON "telematics_samples" ("vehicle_id", "sample_reason", "recorded_at");

CREATE TABLE IF NOT EXISTS "fault_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle reporting the fault.
	"vehicle_id" BIGINT NOT NULL,
	-- Diagnostic trouble code as reported on the bus, e.g. P0420 or an OEM-specific code.
	"code" VARCHAR(16) NOT NULL,
	-- Human-readable meaning, resolved at ingest so the workshop is not looking up codes by hand.
	"description" VARCHAR(240),
	-- info | warning | critical. Critical is the one that pulls a vehicle off the road before its next scheduled service.
	"severity" VARCHAR(16) NOT NULL DEFAULT 'warning',
	-- True while the ECU still reports the code. Cleared faults are kept because an intermittent fault that returns three times is a different problem from three unrelated faults.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- First time this code appeared in the current active window.
	"first_seen_at" TIMESTAMPTZ NOT NULL,
	-- Most recent report of the same code. Updated in place instead of inserting, which is what stops a stuck sensor writing a row every thirty seconds.
	"last_seen_at" TIMESTAMPTZ NOT NULL,
	-- How many times the code was reported in this window. The count is the signal; the individual pings are not.
	"occurrence_count" INTEGER NOT NULL DEFAULT 1,
	-- When the code stopped being reported or was cleared at the workshop. Null while active.
	"cleared_at" TIMESTAMPTZ,
	-- Work order raised for this fault, if any. Null when the fault cleared itself or was judged cosmetic.
	"work_order_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "fault_events" IS 'One row per fault occurrence window, deduplicated by code. Faults are the opposite shape from telematics samples: they are rare, they matter individually, and a repeat is meaningful, so they get their own table rather than a column on the sample.';
COMMENT ON COLUMN "fault_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "fault_events"."vehicle_id" IS 'Vehicle reporting the fault.';
COMMENT ON COLUMN "fault_events"."code" IS 'Diagnostic trouble code as reported on the bus, e.g. P0420 or an OEM-specific code.';
COMMENT ON COLUMN "fault_events"."description" IS 'Human-readable meaning, resolved at ingest so the workshop is not looking up codes by hand.';
COMMENT ON COLUMN "fault_events"."severity" IS 'info | warning | critical. Critical is the one that pulls a vehicle off the road before its next scheduled service.';
COMMENT ON COLUMN "fault_events"."is_active" IS 'True while the ECU still reports the code. Cleared faults are kept because an intermittent fault that returns three times is a different problem from three unrelated faults.';
COMMENT ON COLUMN "fault_events"."first_seen_at" IS 'First time this code appeared in the current active window.';
COMMENT ON COLUMN "fault_events"."last_seen_at" IS 'Most recent report of the same code. Updated in place instead of inserting, which is what stops a stuck sensor writing a row every thirty seconds.';
COMMENT ON COLUMN "fault_events"."occurrence_count" IS 'How many times the code was reported in this window. The count is the signal; the individual pings are not.';
COMMENT ON COLUMN "fault_events"."cleared_at" IS 'When the code stopped being reported or was cleared at the workshop. Null while active.';
COMMENT ON COLUMN "fault_events"."work_order_id" IS 'Work order raised for this fault, if any. Null when the fault cleared itself or was judged cosmetic.';

CREATE INDEX "idx_faults_vehicle_code_active"
ON "fault_events" ("vehicle_id", "code", "is_active");
CREATE INDEX "idx_faults_severity_active"
ON "fault_events" ("severity", "is_active");

CREATE TABLE IF NOT EXISTS "maintenance_schedules" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle this schedule applies to. Per vehicle rather than per model, because a van on motorways and the same van on building sites are not on the same interval.
	"vehicle_id" BIGINT NOT NULL,
	-- oil_change | brake_service | tyre_rotation | safety_inspection | lift_test. What is due, not who does it.
	"service_type" VARCHAR(48) NOT NULL,
	-- Distance between services. Null when the item is purely time-based, such as an annual inspection.
	"interval_km" INTEGER,
	-- Days between services. Null when the item is purely distance-based. A vehicle that barely moves still needs its oil changed, which is why both columns exist.
	"interval_days" INTEGER,
	-- Odometer at the last completed service, the baseline for the next distance-based due point.
	"last_service_km" INTEGER,
	-- Date of the last completed service, the baseline for the next date-based due point.
	"last_service_on" DATE,
	-- Computed next due odometer. Stored so the due list is a range scan against vehicles.odometer_km rather than arithmetic across every row.
	"next_due_km" INTEGER,
	-- Computed next due date. Whichever of the two due points is reached first wins.
	"next_due_on" DATE,
	-- False when the item no longer applies, for example after a vehicle is converted to electric and the oil schedule is retired.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "maintenance_schedules" IS 'What is due and when, per vehicle. Both interval columns are nullable and either may fire: the due date is the earlier of the distance projection and the date projection, which is the rule every fleet actually operates by and almost every schema gets wrong by picking one.';
COMMENT ON COLUMN "maintenance_schedules"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "maintenance_schedules"."vehicle_id" IS 'Vehicle this schedule applies to. Per vehicle rather than per model, because a van on motorways and the same van on building sites are not on the same interval.';
COMMENT ON COLUMN "maintenance_schedules"."service_type" IS 'oil_change | brake_service | tyre_rotation | safety_inspection | lift_test. What is due, not who does it.';
COMMENT ON COLUMN "maintenance_schedules"."interval_km" IS 'Distance between services. Null when the item is purely time-based, such as an annual inspection.';
COMMENT ON COLUMN "maintenance_schedules"."interval_days" IS 'Days between services. Null when the item is purely distance-based. A vehicle that barely moves still needs its oil changed, which is why both columns exist.';
COMMENT ON COLUMN "maintenance_schedules"."last_service_km" IS 'Odometer at the last completed service, the baseline for the next distance-based due point.';
COMMENT ON COLUMN "maintenance_schedules"."last_service_on" IS 'Date of the last completed service, the baseline for the next date-based due point.';
COMMENT ON COLUMN "maintenance_schedules"."next_due_km" IS 'Computed next due odometer. Stored so the due list is a range scan against vehicles.odometer_km rather than arithmetic across every row.';
COMMENT ON COLUMN "maintenance_schedules"."next_due_on" IS 'Computed next due date. Whichever of the two due points is reached first wins.';
COMMENT ON COLUMN "maintenance_schedules"."is_active" IS 'False when the item no longer applies, for example after a vehicle is converted to electric and the oil schedule is retired.';

CREATE UNIQUE INDEX "uq_schedules_vehicle_service"
ON "maintenance_schedules" ("vehicle_id", "service_type");
CREATE INDEX "idx_schedules_due_date"
ON "maintenance_schedules" ("next_due_on");

CREATE TABLE IF NOT EXISTS "work_orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle being worked on.
	"vehicle_id" BIGINT NOT NULL,
	-- Schedule this order satisfies. Null for unplanned repairs, and the ratio of null to non-null is the fleet health metric everybody eventually asks for.
	"maintenance_schedule_id" BIGINT,
	-- Reference quoted to the workshop and on the invoice.
	"order_number" VARCHAR(32) NOT NULL UNIQUE,
	-- preventive | repair | recall | accident | inspection_defect. Preventive against repair is the split that justifies the maintenance budget.
	"work_order_type" VARCHAR(24) NOT NULL DEFAULT 'repair',
	-- open | in_progress | awaiting_parts | completed | cancelled. awaiting_parts is its own state because it is the usual reason a vehicle is off the road for a week.
	"status" VARCHAR(24) NOT NULL DEFAULT 'open',
	-- When the order was raised.
	"opened_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the vehicle was released. The gap from opened_at is downtime, which costs more than the repair.
	"completed_at" TIMESTAMPTZ,
	-- Odometer at intake, snapshotted so the schedule baseline can be advanced accurately.
	"odometer_km" INTEGER,
	-- Workshop that did the work, internal or external.
	"vendor_name" VARCHAR(160),
	-- Hours billed, kept apart from cost so internal labour can be valued differently from a garage invoice.
	"labour_hours" NUMERIC(6,2),
	-- Labour charge in minor currency units.
	"labour_cost_minor" BIGINT NOT NULL DEFAULT 0,
	-- Sum of the parts lines in minor units, maintained as lines are added so cost reporting does not aggregate on every read.
	"parts_cost_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency of both cost columns.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "work_orders" IS 'A single visit to a workshop. It is the join point between why a vehicle was taken off the road — a schedule, a fault, a failed inspection, an incident — and what it cost.';
COMMENT ON COLUMN "work_orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "work_orders"."vehicle_id" IS 'Vehicle being worked on.';
COMMENT ON COLUMN "work_orders"."maintenance_schedule_id" IS 'Schedule this order satisfies. Null for unplanned repairs, and the ratio of null to non-null is the fleet health metric everybody eventually asks for.';
COMMENT ON COLUMN "work_orders"."order_number" IS 'Reference quoted to the workshop and on the invoice.';
COMMENT ON COLUMN "work_orders"."work_order_type" IS 'preventive | repair | recall | accident | inspection_defect. Preventive against repair is the split that justifies the maintenance budget.';
COMMENT ON COLUMN "work_orders"."status" IS 'open | in_progress | awaiting_parts | completed | cancelled. awaiting_parts is its own state because it is the usual reason a vehicle is off the road for a week.';
COMMENT ON COLUMN "work_orders"."opened_at" IS 'When the order was raised.';
COMMENT ON COLUMN "work_orders"."completed_at" IS 'When the vehicle was released. The gap from opened_at is downtime, which costs more than the repair.';
COMMENT ON COLUMN "work_orders"."odometer_km" IS 'Odometer at intake, snapshotted so the schedule baseline can be advanced accurately.';
COMMENT ON COLUMN "work_orders"."vendor_name" IS 'Workshop that did the work, internal or external.';
COMMENT ON COLUMN "work_orders"."labour_hours" IS 'Hours billed, kept apart from cost so internal labour can be valued differently from a garage invoice.';
COMMENT ON COLUMN "work_orders"."labour_cost_minor" IS 'Labour charge in minor currency units.';
COMMENT ON COLUMN "work_orders"."parts_cost_minor" IS 'Sum of the parts lines in minor units, maintained as lines are added so cost reporting does not aggregate on every read.';
COMMENT ON COLUMN "work_orders"."currency_code" IS 'ISO 4217 currency of both cost columns.';

CREATE INDEX "idx_work_orders_vehicle_opened"
ON "work_orders" ("vehicle_id", "opened_at");
CREATE INDEX "idx_work_orders_status"
ON "work_orders" ("status");

CREATE TABLE IF NOT EXISTS "parts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Manufacturer or supplier part number, the identifier the stores counter recognises.
	"part_number" VARCHAR(64) NOT NULL UNIQUE,
	-- Description printed on the work order.
	"name" VARCHAR(200) NOT NULL,
	-- Maker of the part, needed to distinguish an OEM part from an aftermarket equivalent with the same fitment.
	"manufacturer" VARCHAR(120),
	-- Current purchase cost in minor units. The cost actually charged is snapshotted on the line, because this one moves.
	"unit_cost_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217 currency of unit_cost_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Units in the parts store. A single counter on purpose: a fleet store is one shelf unit, and bin-level stock with a movement log is the warehouse problem, modelled in the warehouse inventory example.
	"quantity_on_hand" INTEGER NOT NULL DEFAULT 0,
	-- Level at which the part is reordered, so a common consumable does not strand a vehicle in awaiting_parts.
	"reorder_point" INTEGER,
	-- False when superseded by a newer part number; history keeps resolving.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "parts" IS 'The parts catalogue and its stock counter. Deliberately shallow — the interesting question here is which vehicle consumed what, not where on the shelf it sat.';
COMMENT ON COLUMN "parts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "parts"."part_number" IS 'Manufacturer or supplier part number, the identifier the stores counter recognises.';
COMMENT ON COLUMN "parts"."name" IS 'Description printed on the work order.';
COMMENT ON COLUMN "parts"."manufacturer" IS 'Maker of the part, needed to distinguish an OEM part from an aftermarket equivalent with the same fitment.';
COMMENT ON COLUMN "parts"."unit_cost_minor" IS 'Current purchase cost in minor units. The cost actually charged is snapshotted on the line, because this one moves.';
COMMENT ON COLUMN "parts"."currency_code" IS 'ISO 4217 currency of unit_cost_minor.';
COMMENT ON COLUMN "parts"."quantity_on_hand" IS 'Units in the parts store. A single counter on purpose: a fleet store is one shelf unit, and bin-level stock with a movement log is the warehouse problem, modelled in the warehouse inventory example.';
COMMENT ON COLUMN "parts"."reorder_point" IS 'Level at which the part is reordered, so a common consumable does not strand a vehicle in awaiting_parts.';
COMMENT ON COLUMN "parts"."is_active" IS 'False when superseded by a newer part number; history keeps resolving.';

CREATE TABLE IF NOT EXISTS "work_order_parts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order the part was consumed on.
	"work_order_id" BIGINT NOT NULL,
	-- Part fitted.
	"part_id" BIGINT NOT NULL,
	-- Units fitted. A part can appear twice on one order at different prices, which is why this is not a composite key on the two ids.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	-- Cost charged for this line, snapshotted at fitting so a later price change cannot rewrite last year total.
	"unit_cost_minor" BIGINT NOT NULL,
	-- ISO 4217 currency of unit_cost_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "work_order_parts" IS 'Parts consumed per work order. Consumption history per part number is what turns a warranty claim or a recurring failure pattern into a query.';
COMMENT ON COLUMN "work_order_parts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "work_order_parts"."work_order_id" IS 'Order the part was consumed on.';
COMMENT ON COLUMN "work_order_parts"."part_id" IS 'Part fitted.';
COMMENT ON COLUMN "work_order_parts"."quantity" IS 'Units fitted. A part can appear twice on one order at different prices, which is why this is not a composite key on the two ids.';
COMMENT ON COLUMN "work_order_parts"."unit_cost_minor" IS 'Cost charged for this line, snapshotted at fitting so a later price change cannot rewrite last year total.';
COMMENT ON COLUMN "work_order_parts"."currency_code" IS 'ISO 4217 currency of unit_cost_minor.';

CREATE INDEX "idx_wo_parts_order"
ON "work_order_parts" ("work_order_id");
CREATE INDEX "idx_wo_parts_part"
ON "work_order_parts" ("part_id");

CREATE TABLE IF NOT EXISTS "fuel_purchases" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle fuelled, resolved from the fuel card or the plate typed at the pump.
	"vehicle_id" BIGINT NOT NULL,
	-- Driver who bought it. Null when the card transaction cannot be matched to an assignment, which happens often enough that it must be nullable.
	"driver_id" BIGINT,
	-- Transaction time from the card network, used to match against the assignment interval.
	"purchased_at" TIMESTAMPTZ NOT NULL,
	-- Volume dispensed, or kilowatt-hours for an electric vehicle. Compared against tank capacity: more litres than the tank holds is the oldest fuel fraud there is.
	"litres" NUMERIC(8,2) NOT NULL,
	-- Price per litre in minor units at the pump.
	"unit_price_minor" BIGINT NOT NULL,
	-- Total charged in minor units. Stored rather than multiplied, because the card network total is authoritative and rounds its own way.
	"total_minor" BIGINT NOT NULL,
	-- ISO 4217 currency of the transaction, which differs from the home currency on cross-border trips.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Odometer entered at the pump. Wrong often enough that consumption is sanity-checked against telematics before it is trusted.
	"odometer_km" INTEGER,
	-- Last four digits of the fuel card. Never the full number — this table has no business holding one.
	"card_last4" CHAR(4),
	-- Station name from the card feed, used to spot a driver routinely filling at the most expensive forecourt on the route.
	"merchant" VARCHAR(160),
	-- Set when an automated check fails — volume over tank capacity, two fills in different cities within an hour, a fill while the ignition was off elsewhere.
	"is_flagged" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "fuel_purchases" IS 'One row per fuel or charging transaction. Cost per kilometre falls out of this joined to the odometer, and the anomaly checks that matter are all comparisons between this row and where the vehicle actually was.';
COMMENT ON COLUMN "fuel_purchases"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "fuel_purchases"."vehicle_id" IS 'Vehicle fuelled, resolved from the fuel card or the plate typed at the pump.';
COMMENT ON COLUMN "fuel_purchases"."driver_id" IS 'Driver who bought it. Null when the card transaction cannot be matched to an assignment, which happens often enough that it must be nullable.';
COMMENT ON COLUMN "fuel_purchases"."purchased_at" IS 'Transaction time from the card network, used to match against the assignment interval.';
COMMENT ON COLUMN "fuel_purchases"."litres" IS 'Volume dispensed, or kilowatt-hours for an electric vehicle. Compared against tank capacity: more litres than the tank holds is the oldest fuel fraud there is.';
COMMENT ON COLUMN "fuel_purchases"."unit_price_minor" IS 'Price per litre in minor units at the pump.';
COMMENT ON COLUMN "fuel_purchases"."total_minor" IS 'Total charged in minor units. Stored rather than multiplied, because the card network total is authoritative and rounds its own way.';
COMMENT ON COLUMN "fuel_purchases"."currency_code" IS 'ISO 4217 currency of the transaction, which differs from the home currency on cross-border trips.';
COMMENT ON COLUMN "fuel_purchases"."odometer_km" IS 'Odometer entered at the pump. Wrong often enough that consumption is sanity-checked against telematics before it is trusted.';
COMMENT ON COLUMN "fuel_purchases"."card_last4" IS 'Last four digits of the fuel card. Never the full number — this table has no business holding one.';
COMMENT ON COLUMN "fuel_purchases"."merchant" IS 'Station name from the card feed, used to spot a driver routinely filling at the most expensive forecourt on the route.';
COMMENT ON COLUMN "fuel_purchases"."is_flagged" IS 'Set when an automated check fails — volume over tank capacity, two fills in different cities within an hour, a fill while the ignition was off elsewhere.';

CREATE INDEX "idx_fuel_vehicle_time"
ON "fuel_purchases" ("vehicle_id", "purchased_at");
CREATE INDEX "idx_fuel_flagged"
ON "fuel_purchases" ("is_flagged");

CREATE TABLE IF NOT EXISTS "inspections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle inspected.
	"vehicle_id" BIGINT NOT NULL,
	-- Person who carried it out. Null for a third-party statutory inspection.
	"driver_id" BIGINT,
	-- pre_trip | post_trip | periodic | statutory | lease_return. Pre-trip checks are a legal requirement in most jurisdictions and are the cheapest defect detector a fleet has.
	"inspection_type" VARCHAR(32) NOT NULL DEFAULT 'pre_trip',
	-- When the walkaround happened. A pre-trip check recorded after the trip started is itself a finding.
	"performed_at" TIMESTAMPTZ NOT NULL,
	-- Odometer at inspection.
	"odometer_km" INTEGER,
	-- pass | pass_with_defects | fail. pass_with_defects is the useful middle: roadworthy today, on the workshop list tomorrow.
	"result" VARCHAR(24) NOT NULL DEFAULT 'pass',
	-- Checklist items that failed, as a small document. Schemaless because the checklist differs per vehicle type and changes with regulation, and no report joins to an individual item.
	"defects" JSONB,
	-- Work order raised from the findings. Null when nothing was found, and a fail with no work order is an audit exception.
	"work_order_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "inspections" IS 'Walkaround and statutory checks. Kept separate from work orders because an inspection is evidence that a check happened at a time, and that record must survive whether or not it led to any work.';
COMMENT ON COLUMN "inspections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "inspections"."vehicle_id" IS 'Vehicle inspected.';
COMMENT ON COLUMN "inspections"."driver_id" IS 'Person who carried it out. Null for a third-party statutory inspection.';
COMMENT ON COLUMN "inspections"."inspection_type" IS 'pre_trip | post_trip | periodic | statutory | lease_return. Pre-trip checks are a legal requirement in most jurisdictions and are the cheapest defect detector a fleet has.';
COMMENT ON COLUMN "inspections"."performed_at" IS 'When the walkaround happened. A pre-trip check recorded after the trip started is itself a finding.';
COMMENT ON COLUMN "inspections"."odometer_km" IS 'Odometer at inspection.';
COMMENT ON COLUMN "inspections"."result" IS 'pass | pass_with_defects | fail. pass_with_defects is the useful middle: roadworthy today, on the workshop list tomorrow.';
COMMENT ON COLUMN "inspections"."defects" IS 'Checklist items that failed, as a small document. Schemaless because the checklist differs per vehicle type and changes with regulation, and no report joins to an individual item.';
COMMENT ON COLUMN "inspections"."work_order_id" IS 'Work order raised from the findings. Null when nothing was found, and a fail with no work order is an audit exception.';

CREATE INDEX "idx_inspections_vehicle_time"
ON "inspections" ("vehicle_id", "performed_at");
CREATE INDEX "idx_inspections_result_time"
ON "inspections" ("result", "performed_at");

CREATE TABLE IF NOT EXISTS "incidents" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Vehicle involved.
	"vehicle_id" BIGINT NOT NULL,
	-- Driver at the wheel, resolved from the assignment interval. Null for theft or damage in a yard.
	"driver_id" BIGINT,
	-- When it happened, as opposed to when it was reported — the gap between the two is itself a reporting-culture metric.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- When the fleet learned about it.
	"reported_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- collision | breakdown | theft | vandalism | citation | injury. Citations are here because they attach to a driver and a vehicle at a time like everything else.
	"incident_type" VARCHAR(24) NOT NULL DEFAULT 'collision',
	-- WGS84 latitude of the incident, so it can be corroborated against telematics.
	"latitude" NUMERIC(9,6),
	-- WGS84 longitude.
	"longitude" NUMERIC(9,6),
	-- Where it happened in words, for the insurer who will not accept coordinates.
	"location_description" VARCHAR(240),
	-- Whether the fleet is judged liable. Nullable and stays null for months, because liability is decided long after the event.
	"at_fault" BOOLEAN,
	-- Narrative account, captured while memories are fresh.
	"description" TEXT,
	-- Reference from the attending authority, if any.
	"police_report_number" VARCHAR(64),
	-- Insurer claim reference once opened.
	"claim_number" VARCHAR(64),
	-- Best estimate of total cost in minor units including third-party liability, which is usually far more than the repair on the work order.
	"estimated_cost_minor" BIGINT,
	-- ISO 4217 currency of estimated_cost_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- reported | under_review | claim_open | closed. Incidents stay open far longer than the repair they caused.
	"status" VARCHAR(24) NOT NULL DEFAULT 'reported',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "incidents" IS 'Anything that costs money and was not planned. It is separate from work orders because the insurance and liability lifecycle outlives the repair by months, and because not every incident produces a repair.';
COMMENT ON COLUMN "incidents"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "incidents"."vehicle_id" IS 'Vehicle involved.';
COMMENT ON COLUMN "incidents"."driver_id" IS 'Driver at the wheel, resolved from the assignment interval. Null for theft or damage in a yard.';
COMMENT ON COLUMN "incidents"."occurred_at" IS 'When it happened, as opposed to when it was reported — the gap between the two is itself a reporting-culture metric.';
COMMENT ON COLUMN "incidents"."reported_at" IS 'When the fleet learned about it.';
COMMENT ON COLUMN "incidents"."incident_type" IS 'collision | breakdown | theft | vandalism | citation | injury. Citations are here because they attach to a driver and a vehicle at a time like everything else.';
COMMENT ON COLUMN "incidents"."latitude" IS 'WGS84 latitude of the incident, so it can be corroborated against telematics.';
COMMENT ON COLUMN "incidents"."longitude" IS 'WGS84 longitude.';
COMMENT ON COLUMN "incidents"."location_description" IS 'Where it happened in words, for the insurer who will not accept coordinates.';
COMMENT ON COLUMN "incidents"."at_fault" IS 'Whether the fleet is judged liable. Nullable and stays null for months, because liability is decided long after the event.';
COMMENT ON COLUMN "incidents"."description" IS 'Narrative account, captured while memories are fresh.';
COMMENT ON COLUMN "incidents"."police_report_number" IS 'Reference from the attending authority, if any.';
COMMENT ON COLUMN "incidents"."claim_number" IS 'Insurer claim reference once opened.';
COMMENT ON COLUMN "incidents"."estimated_cost_minor" IS 'Best estimate of total cost in minor units including third-party liability, which is usually far more than the repair on the work order.';
COMMENT ON COLUMN "incidents"."currency_code" IS 'ISO 4217 currency of estimated_cost_minor.';
COMMENT ON COLUMN "incidents"."status" IS 'reported | under_review | claim_open | closed. Incidents stay open far longer than the repair they caused.';

CREATE INDEX "idx_incidents_vehicle_time"
ON "incidents" ("vehicle_id", "occurred_at");
CREATE INDEX "idx_incidents_driver_time"
ON "incidents" ("driver_id", "occurred_at");

